import frappe

def before_submit(doc, method):
    if doc.custom_approval_status == 'Draft':
        frappe.throw("Cannot submit draft project. Please get approval first.")
    
    if doc.custom_approval_status == 'Rejected':
        frappe.throw("Cannot submit rejected project.")

# Server Script for Lead - Event: After Insert
# This script automatically creates Customer and Address when a Lead is saved

# Only create customer if it doesn't already exist
if doc.customer:
    frappe.msgprint(_("Customer already exists for this lead"))
else:
    created_records = []
    skipped_records = []
    
    try:
        # Validate required fields first
        if not doc.lead_name and not doc.company_name:
            skipped_records.append("Lead Name or Company Name is required to create customer")
        else:
            # Determine customer name and type
            if doc.company_name:
                customer_name = doc.company_name
                customer_type = "Company"
            elif doc.lead_name:
                customer_name = doc.lead_name
                customer_type = "Individual"
            else:
                # Construct name from individual fields
                name_parts = []
                if doc.get('first_name'):
                    name_parts.append(doc.first_name)
                if doc.get('middle_name'):
                    name_parts.append(doc.middle_name)
                if doc.get('last_name'):
                    name_parts.append(doc.last_name)
                
                customer_name = " ".join(name_parts) if name_parts else "New Customer"
                customer_type = "Individual"
            
            # Check if customer already exists to avoid duplicates
            existing_customer = frappe.db.exists("Customer", {"customer_name": customer_name})
            
            if existing_customer:
                skipped_records.append(f"Customer with name '{customer_name}' already exists ({existing_customer})")
                # Still update the lead with customer reference
                frappe.db.set_value("Lead", doc.name, "customer", existing_customer)
            else:
                try:
                    # Create customer document
                    customer_doc = frappe.new_doc("Customer")
                    customer_doc.customer_name = customer_name
                    customer_doc.customer_type = customer_type
                    customer_doc.naming_series = "CUST-.YYYY.-"  # Set naming series
                    
                    print("Creating customer:", customer_name)
                    print("Customer type:", customer_type)
                    
                    # Map lead fields to customer fields
                    if doc.gender:
                        customer_doc.gender = doc.gender
                    if doc.salutation:
                        customer_doc.salutation = doc.salutation
                    if doc.lead_owner:
                        customer_doc.account_manager = doc.lead_owner
                    if doc.image:
                        customer_doc.image = doc.image
                    if doc.mobile_no:
                        customer_doc.mobile_no = doc.mobile_no
                    if doc.email_id:
                        customer_doc.email_id = doc.email_id
                    if doc.phone:
                        customer_doc.phone = doc.phone
                    if doc.website:
                        customer_doc.website = doc.website
                    if doc.industry:
                        customer_doc.industry = doc.industry
                    if doc.get('market_segment'):
                        customer_doc.market_segment = doc.market_segment
                    if doc.get('annual_revenue'):
                        customer_doc.annual_revenue = doc.annual_revenue
                    if doc.company:
                        customer_doc.company = doc.company
                    if doc.get('language'):
                        customer_doc.language = doc.language
                    if doc.get('fax'):
                        customer_doc.fax = doc.fax
                    
                    # Company-specific fields
                    if customer_type == "Company" and doc.get('no_of_employees'):
                        customer_doc.no_of_employees = doc.no_of_employees
                    
                    # Save the customer record
                    customer_doc.insert()
                    created_records.append(f"Customer: {customer_doc.name}")
                    
                    # Update lead with customer reference
                    frappe.db.set_value("Lead", doc.name, "customer", customer_doc.name)
                    
                    # Update customer with lead reference (this will be handled by Customer Before Save script)
                    # But we can also do it directly here as a fallback
                    try:
                        frappe.db.set_value("Customer", customer_doc.name, "lead_name", doc.name)
                        frappe.db.commit()
                        print(f"Updated customer {customer_doc.name} with lead_name: {doc.name}")
                    except Exception as update_error:
                        print(f"Direct update failed, will be handled by Customer script: {update_error}")
                    
                    # Create address if we have address data
                    has_basic_address = any([doc.city, doc.state, doc.country])
                    has_building_info = any([
                        doc.get('custom_building_name'),
                        doc.get('custom_bulding__apartment__villa__office_number')
                    ])
                    
                    if has_basic_address or has_building_info:
                        try:
                            # Prepare address lines
                            address_line1 = ""
                            address_line2 = ""
                            
                            # Build address from custom fields
                            if doc.get('custom_building_name'):
                                address_line1 = doc.custom_building_name
                            
                            if doc.get('custom_bulding__apartment__villa__office_number'):
                                address_line2 = doc.custom_bulding__apartment__villa__office_number
                            
                            # Create address title
                            address_title = doc.lead_name or customer_name
                            if doc.city:
                                address_title += f" - {doc.custom_property_area}"
                            
                            print("Creating address:", address_title)
                            print("Address line 1:", address_line1)
                            print("Address line 2:", address_line2)
                            print("City:", doc.city or "")
                            
                            # Create address document
                            address_doc = frappe.new_doc("Address")
                            address_doc.address_title = address_title
                            address_doc.address_type = "Billing"
                            address_doc.address_line1 = address_line1
                            address_doc.address_line2 = address_line2
                            address_doc.city = doc.custom_property_area or ""
                            address_doc.state = doc.state or ""
                            address_doc.country = doc.country or ""
                            address_doc.is_primary_address = 1
                            address_doc.is_shipping_address = 1
                            
                            # Add contact info to address
                            if doc.email_id:
                                address_doc.email_id = doc.email_id
                            if doc.phone:
                                address_doc.phone = doc.phone
                            elif doc.mobile_no:
                                address_doc.phone = doc.mobile_no
                            if doc.get('fax'):
                                address_doc.fax = doc.fax
                            
                            # Link address to customer
                            address_doc.append("links", {
                                "link_doctype": "Customer",
                                "link_name": customer_doc.name
                            })
                            
                            # Save the address record
                            address_doc.insert()
                            created_records.append(f"Address: {address_doc.name}")
                            
                        except Exception as e:
                            error_msg = f"Error creating address: {str(e)}"
                            frappe.log_error(f"Error creating address for customer {customer_doc.name}: {error_msg}")
                            skipped_records.append(error_msg)
                    else:
                        skipped_records.append("No address data found to create address record")
                    
                except Exception as e:
                    error_msg = f"Error creating customer: {str(e)}"
                    frappe.log_error(f"Error creating customer from lead {doc.name}: {error_msg}")
                    skipped_records.append(error_msg)
        
        # Show result messages
        messages = []
        if created_records:
            messages.append(f"✅ Created {len(created_records)} records:")
            for record in created_records:
                messages.append(f"  • {record}")
        if skipped_records:
            messages.append(f"⚠️ Issues found:")
            for skip in skipped_records:
                messages.append(f"  • {skip}")
        
        if messages:
            frappe.msgprint("<br>".join(messages), title="Customer Creation Result")
            
    except Exception as e:
        error_msg = f"Unexpected error: {str(e)}"
        frappe.log_error(f"Unexpected error in lead customer creation: {error_msg}")
        frappe.msgprint(f"❌ {error_msg}", title="Error")

if doc.email:
    frappe.sendmail(
        recipients=doc.email,
        subject=f"Salary Slip for {doc.month} {doc.fiscal_year}",
        message=f"Dear {doc.employee_name},<br><br>Please find your salary slip attached.",
        attachments=[
            frappe.attach_print("Salary Slip", doc.name, file_name=f"Salary_Slip_{doc.month}_{doc.fiscal_year}.pdf")
        ]
    )

if doc.email:
    usersetting = frappe.get_doc({
        "doctype": "User Settings",
        "user":doc.email
    })
    usersetting.insert()
